-- Deal step 6: apply the result to the game tables
-- Generated by scripts/generate/generate.mjs from shared/deal/ (workstream B). Don't edit by hand.

INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_' || LeaderType, 'KIND_TRAIT' FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1));
INSERT OR IGNORE INTO Traits (TraitType, Name, Description, InternalOnly) SELECT 'TRAIT_LSHUF_' || x.LeaderType, (SELECT lx.AbilityName FROM LShufWork_L lx WHERE lx.LeaderType = x.LeaderType), 'LOC_LSHUF_TRAIT_DEALT_DESCRIPTION', 1
  FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1)) x WHERE 'TRAIT_LSHUF_' || x.LeaderType IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_PERSONA_' || LeaderType, 'KIND_TRAIT' FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1) UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffA FROM LShufWork_Cfg) = 1 AND RA IS NULL);
INSERT OR IGNORE INTO Traits (TraitType, Name, Description, InternalOnly) SELECT 'TRAIT_LSHUF_PERSONA_' || x.LeaderType, NULL, NULL, 1
  FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1) UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffA FROM LShufWork_Cfg) = 1 AND RA IS NULL) x WHERE 'TRAIT_LSHUF_PERSONA_' || x.LeaderType IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_EQUAL_ACTIONS', 'KIND_TRAIT' WHERE EXISTS (SELECT 1 FROM LShufResultAttributes WHERE TraitType = 'TRAIT_LSHUF_EQUAL_ACTIONS');
INSERT OR IGNORE INTO Traits (TraitType, Name, Description, InternalOnly) SELECT 'TRAIT_LSHUF_EQUAL_ACTIONS', NULL, NULL, 1
  WHERE EXISTS (SELECT 1 FROM LShufResultAttributes WHERE TraitType = 'TRAIT_LSHUF_EQUAL_ACTIONS') AND 'TRAIT_LSHUF_EQUAL_ACTIONS' IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO TraitModifiers (ModifierId, TraitType)
  SELECT DISTINCT tm.ModifierId, 'TRAIT_LSHUF_EQUAL_ACTIONS' FROM TraitModifiers tm JOIN Modifiers m ON m.ModifierId = tm.ModifierId
  JOIN DynamicModifiers d ON d.ModifierType = m.ModifierType
  WHERE tm.TraitType IN (SELECT TraitType FROM LShufAttributeTraits) AND d.EffectType = 'EFFECT_DIPLOMACY_GRANT_DIPLOMATIC_ACTION'
    AND 'TRAIT_LSHUF_EQUAL_ACTIONS' IN (SELECT TraitType FROM Traits);

INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_EXTRA' || Copy || '_' || TraitType, 'KIND_TRAIT' FROM (SELECT DISTINCT Copy, TraitType FROM LShufResultAttributes WHERE Copy > 0)
  WHERE TraitType IN (SELECT TraitType FROM Traits);
INSERT OR IGNORE INTO Traits (TraitType, Name, Description, InternalOnly) SELECT 'TRAIT_LSHUF_EXTRA' || Copy || '_' || TraitType, NULL, NULL, 1
  FROM (SELECT DISTINCT Copy, TraitType FROM LShufResultAttributes WHERE Copy > 0) WHERE 'TRAIT_LSHUF_EXTRA' || Copy || '_' || TraitType IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO Modifiers (ModifierId, ModifierType, NewOnly, OwnerRequirementSetId, OwnerStackLimit, Permanent, RunOnce,
    SubjectRequirementSetId, SubjectStackLimit)
  SELECT 'LSHUF_EXTRA' || p.Copy || '__' || p.ModifierId, p.ModifierType, p.NewOnly, p.OwnerRequirementSetId, p.OwnerStackLimit, p.Permanent,
    p.RunOnce, p.SubjectRequirementSetId, p.SubjectStackLimit FROM (SELECT x.Copy AS Copy, x.TraitType AS TraitType, m.* FROM (SELECT DISTINCT Copy, TraitType FROM LShufResultAttributes WHERE Copy > 0) x
    JOIN TraitModifiers tm ON tm.TraitType = x.TraitType JOIN Modifiers m ON m.ModifierId = tm.ModifierId
    JOIN DynamicModifiers d ON d.ModifierType = m.ModifierType WHERE d.EffectType <> 'EFFECT_DIPLOMACY_GRANT_DIPLOMATIC_ACTION') p;
INSERT OR IGNORE INTO ModifierArguments (ModifierId, Name, Extra, SecondExtra, Type, Value)
  SELECT 'LSHUF_EXTRA' || p.Copy || '__' || p.ModifierId, a.Name, a.Extra, a.SecondExtra, a.Type, a.Value FROM (SELECT x.Copy AS Copy, x.TraitType AS TraitType, m.* FROM (SELECT DISTINCT Copy, TraitType FROM LShufResultAttributes WHERE Copy > 0) x
    JOIN TraitModifiers tm ON tm.TraitType = x.TraitType JOIN Modifiers m ON m.ModifierId = tm.ModifierId
    JOIN DynamicModifiers d ON d.ModifierType = m.ModifierType WHERE d.EffectType <> 'EFFECT_DIPLOMACY_GRANT_DIPLOMATIC_ACTION') p
  JOIN ModifierArguments a ON a.ModifierId = p.ModifierId
  WHERE 'LSHUF_EXTRA' || p.Copy || '__' || p.ModifierId IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO TraitModifiers (ModifierId, TraitType)
  SELECT 'LSHUF_EXTRA' || p.Copy || '__' || p.ModifierId, 'TRAIT_LSHUF_EXTRA' || p.Copy || '_' || p.TraitType FROM (SELECT x.Copy AS Copy, x.TraitType AS TraitType, m.* FROM (SELECT DISTINCT Copy, TraitType FROM LShufResultAttributes WHERE Copy > 0) x
    JOIN TraitModifiers tm ON tm.TraitType = x.TraitType JOIN Modifiers m ON m.ModifierId = tm.ModifierId
    JOIN DynamicModifiers d ON d.ModifierType = m.ModifierType WHERE d.EffectType <> 'EFFECT_DIPLOMACY_GRANT_DIPLOMATIC_ACTION') p
  WHERE 'LSHUF_EXTRA' || p.Copy || '__' || p.ModifierId IN (SELECT ModifierId FROM Modifiers)
    AND 'TRAIT_LSHUF_EXTRA' || p.Copy || '_' || p.TraitType IN (SELECT TraitType FROM Traits);

CREATE TABLE IF NOT EXISTS LShufWork_Copy (Receiver TEXT, ModifierId TEXT, PRIMARY KEY (Receiver, ModifierId));
DELETE FROM LShufWork_Copy;
INSERT OR IGNORE INTO LShufWork_Copy (Receiver, ModifierId) SELECT p.LeaderType, tm.ModifierId FROM LShufResultPieces p JOIN TraitModifiers tm ON tm.TraitType = (SELECT lx.Ability FROM LShufWork_L lx WHERE lx.LeaderType = p.FromLeaderType)
  WHERE p.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1)) AND p.Kind = 'whole' AND tm.ModifierId NOT IN (SELECT mm.ModifierId FROM LShufMappingModifiers mm JOIN LShufMapping m ON m.PieceId = mm.PieceId
      WHERE m.LeaderType = p.FromLeaderType AND (m.Kind = 'agenda' OR mm.Role = 'agenda'));
INSERT OR IGNORE INTO LShufWork_Copy (Receiver, ModifierId) SELECT p.LeaderType, mm.ModifierId FROM LShufResultPieces p JOIN LShufMappingModifiers mm ON mm.PieceId = p.PieceId
  WHERE p.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1)) AND p.Kind = 'bullet' AND mm.Role IN ('effect', 'hidden')
    AND mm.ModifierId IN (SELECT tm.ModifierId FROM TraitModifiers tm WHERE tm.TraitType = (SELECT lx.Ability FROM LShufWork_L lx WHERE lx.LeaderType = p.FromLeaderType));
INSERT OR IGNORE INTO LShufWork_Copy (Receiver, ModifierId) SELECT p.LeaderType, tm.ModifierId FROM LShufResultPieces p JOIN TraitModifiers tm ON tm.TraitType = (SELECT lx.Ability FROM LShufWork_L lx WHERE lx.LeaderType = p.FromLeaderType)
  WHERE p.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1)) AND p.Kind = 'remainder' AND tm.ModifierId NOT IN (SELECT mm.ModifierId FROM LShufMappingModifiers mm JOIN LShufMapping m ON m.PieceId = mm.PieceId
      WHERE m.LeaderType = p.FromLeaderType AND ((m.Kind = 'bullet' AND COALESCE(m.Movable, 1) = 1) OR m.Kind = 'agenda'));
DELETE FROM LShufWork_Copy WHERE ModifierId NOT IN (SELECT ModifierId FROM Modifiers);

INSERT OR IGNORE INTO Modifiers (ModifierId, ModifierType, NewOnly, OwnerRequirementSetId, OwnerStackLimit, Permanent, RunOnce,
    SubjectRequirementSetId, SubjectStackLimit)
  SELECT 'LSHUF_' || c.Receiver || '__' || m.ModifierId, m.ModifierType, m.NewOnly, m.OwnerRequirementSetId, m.OwnerStackLimit, m.Permanent, m.RunOnce,
    m.SubjectRequirementSetId, m.SubjectStackLimit FROM LShufWork_Copy c JOIN Modifiers m ON m.ModifierId = c.ModifierId;
INSERT OR IGNORE INTO ModifierArguments (ModifierId, Name, Extra, SecondExtra, Type, Value)
  SELECT 'LSHUF_' || c.Receiver || '__' || a.ModifierId, a.Name, a.Extra, a.SecondExtra, a.Type,
    CASE WHEN a.Name = 'Tooltip' AND (SELECT l.AbilityName FROM LShufWork_L l WHERE l.LeaderType = c.Receiver) IS NOT NULL THEN (SELECT l.AbilityName FROM LShufWork_L l WHERE l.LeaderType = c.Receiver) ELSE a.Value END
  FROM LShufWork_Copy c JOIN ModifierArguments a ON a.ModifierId = c.ModifierId
  WHERE 'LSHUF_' || c.Receiver || '__' || a.ModifierId IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO ModifierStrings (Context, ModifierId, Text)
  SELECT s.Context, 'LSHUF_' || c.Receiver || '__' || s.ModifierId, s.Text
  FROM LShufWork_Copy c JOIN ModifierStrings s ON s.ModifierId = c.ModifierId
  WHERE 'LSHUF_' || c.Receiver || '__' || s.ModifierId IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO TraitModifiers (ModifierId, TraitType)
  SELECT 'LSHUF_' || c.Receiver || '__' || c.ModifierId, 'TRAIT_LSHUF_' || c.Receiver FROM LShufWork_Copy c
  WHERE 'LSHUF_' || c.Receiver || '__' || c.ModifierId IN (SELECT ModifierId FROM Modifiers)
    AND 'TRAIT_LSHUF_' || c.Receiver IN (SELECT TraitType FROM Traits);
INSERT OR IGNORE INTO TraitModifiers (ModifierId, TraitType)
  SELECT tm.ModifierId, 'TRAIT_LSHUF_PERSONA_' || x.LeaderType FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1) UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffA FROM LShufWork_Cfg) = 1 AND RA IS NULL) x
  JOIN LShufWork_L l ON l.LeaderType = x.LeaderType
  JOIN TraitModifiers tm ON tm.TraitType = (SELECT lx.Ability FROM LShufWork_L lx WHERE lx.LeaderType = l.PersonaFrom)
  WHERE tm.ModifierId IN (SELECT mm.ModifierId FROM LShufMappingModifiers mm JOIN LShufMapping m ON m.PieceId = mm.PieceId
      WHERE m.LeaderType = l.PersonaFrom AND (m.Kind = 'agenda' OR mm.Role = 'agenda')) AND 'TRAIT_LSHUF_PERSONA_' || x.LeaderType IN (SELECT TraitType FROM Traits);

CREATE TABLE IF NOT EXISTS LShufWork_AiSrc (LeaderType TEXT, Trait TEXT, PRIMARY KEY (LeaderType, Trait));
DELETE FROM LShufWork_AiSrc;
INSERT OR IGNORE INTO LShufWork_AiSrc (LeaderType, Trait) SELECT LeaderType, Trait FROM (SELECT DISTINCT p.LeaderType, (SELECT lx.Ability FROM LShufWork_L lx WHERE lx.LeaderType = p.FromLeaderType) AS Trait FROM LShufResultPieces p
    WHERE p.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1))) WHERE Trait IS NOT NULL;
INSERT OR IGNORE INTO AiListTypes (ListType) SELECT 'LSHUF_' || s.LeaderType || '__' || a.ListType FROM LShufWork_AiSrc s JOIN AiLists a ON a.LeaderType = s.Trait;
INSERT OR IGNORE INTO AiLists (LeaderType, ListType, MaxDifficulty, MinDifficulty, System)
  SELECT 'TRAIT_LSHUF_' || s.LeaderType, 'LSHUF_' || s.LeaderType || '__' || a.ListType, a.MaxDifficulty, a.MinDifficulty, a.System
  FROM LShufWork_AiSrc s JOIN AiLists a ON a.LeaderType = s.Trait WHERE 'LSHUF_' || s.LeaderType || '__' || a.ListType IN (SELECT ListType FROM AiListTypes);
INSERT OR IGNORE INTO AiFavoredItems (Favored, Item, ListType, StringVal, Value, MaxDifficulty, MinDifficulty, TooltipString)
  SELECT f.Favored, f.Item, 'LSHUF_' || s.LeaderType || '__' || a.ListType, f.StringVal, f.Value, f.MaxDifficulty, f.MinDifficulty, f.TooltipString
  FROM LShufWork_AiSrc s JOIN AiLists a ON a.LeaderType = s.Trait JOIN AiFavoredItems f ON f.ListType = a.ListType
  WHERE 'LSHUF_' || s.LeaderType || '__' || a.ListType IN (SELECT ListType FROM AiListTypes);

DELETE FROM LeaderTraits WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 OR ((SELECT OffA FROM LShufWork_Cfg) = 1 AND RA IS NULL))
  AND TraitType = (SELECT lx.Ability FROM LShufWork_L lx WHERE lx.LeaderType = LeaderTraits.LeaderType);
DELETE FROM LeaderTraits WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InT = 1 OR ((SELECT OffT FROM LShufWork_Cfg) = 1 AND RT IS NULL)) AND TraitType IN (SELECT TraitType FROM LShufAttributeTraits);
INSERT OR IGNORE INTO LeaderTraits (LeaderType, TraitType) SELECT d.LeaderType, l.Ability FROM LShufWork_Donor d
  JOIN LShufWork_L l ON l.LeaderType = d.Donor
  WHERE d.Axis = 'A' AND (SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1 AND l.Ability IN (SELECT TraitType FROM Traits)
    AND d.LeaderType NOT IN (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1));
INSERT OR IGNORE INTO LeaderTraits (LeaderType, TraitType) SELECT LeaderType, 'TRAIT_LSHUF_' || LeaderType FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1))
  WHERE 'TRAIT_LSHUF_' || LeaderType IN (SELECT TraitType FROM Traits);
INSERT OR IGNORE INTO LeaderTraits (LeaderType, TraitType) SELECT LeaderType, 'TRAIT_LSHUF_PERSONA_' || LeaderType FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1) UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffA FROM LShufWork_Cfg) = 1 AND RA IS NULL)
  WHERE 'TRAIT_LSHUF_PERSONA_' || LeaderType IN (SELECT TraitType FROM Traits);
INSERT OR IGNORE INTO LeaderTraits (LeaderType, TraitType) SELECT r.LeaderType, r.TraitType FROM LShufResultAttributes r
  WHERE r.Copy = 0 AND r.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InT = 1 OR ((SELECT OffT FROM LShufWork_Cfg) = 1 AND RT IS NULL)) AND r.TraitType IN (SELECT TraitType FROM Traits)
    AND r.LeaderType IN (SELECT LeaderType FROM Leaders);
INSERT OR IGNORE INTO LeaderTraits (LeaderType, TraitType) SELECT r.LeaderType, 'TRAIT_LSHUF_EXTRA' || r.Copy || '_' || r.TraitType
  FROM LShufResultAttributes r
  WHERE r.Copy > 0 AND r.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InT = 1 OR ((SELECT OffT FROM LShufWork_Cfg) = 1 AND RT IS NULL)) AND 'TRAIT_LSHUF_EXTRA' || r.Copy || '_' || r.TraitType IN (SELECT TraitType FROM Traits)
    AND r.LeaderType IN (SELECT LeaderType FROM Leaders);

UPDATE ProgressionTreeNodeUnlocks SET RequiredTraitType = (SELECT r.ToTraitType FROM LShufResultUnlocks r
    WHERE r.ProgressionTreeNodeType = ProgressionTreeNodeUnlocks.ProgressionTreeNodeType AND r.TargetType = ProgressionTreeNodeUnlocks.TargetType)
  WHERE RequiredTraitType IN (SELECT Ability FROM LShufWork_L WHERE Ability IS NOT NULL)
    AND EXISTS (SELECT 1 FROM LShufResultUnlocks r WHERE r.ProgressionTreeNodeType = ProgressionTreeNodeUnlocks.ProgressionTreeNodeType
    AND r.TargetType = ProgressionTreeNodeUnlocks.TargetType AND r.FromTraitType = ProgressionTreeNodeUnlocks.RequiredTraitType AND r.ToTraitType IS NOT NULL
      AND r.ToTraitType <> r.FromTraitType AND r.ToTraitType IN (SELECT TraitType FROM Traits));

