DELETE FROM StartBiasNaturalWonders WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'B'
    UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffB FROM LShufWork_Cfg) = 1 AND RB IS NULL);
DELETE FROM StartBiasNaturalWonders WHERE LeaderType IS NULL AND ((SELECT OffB FROM LShufWork_Cfg) = 1 OR ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1 AND CivilizationType IN (SELECT CivilizationType FROM LShufWork_Civ WHERE (SELECT RollBiases FROM LShufWork_Cfg) = 1 OR Donor <> CivilizationType)));
INSERT OR IGNORE INTO StartBiasNaturalWonders (CivilizationType, LeaderType, Score)
  SELECT r.CivilizationType, r.LeaderType, r.Score FROM LShufResultBiases r
  WHERE r.TableName = 'StartBiasNaturalWonders' AND r.Origin <> 'shipped'
    AND (r.LeaderType IS NULL OR r.LeaderType IN (SELECT LeaderType FROM Leaders))
    AND (r.CivilizationType IS NULL OR r.CivilizationType IN (SELECT CivilizationType FROM Civilizations));
DELETE FROM StartBiasIslands WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'B'
    UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffB FROM LShufWork_Cfg) = 1 AND RB IS NULL);
DELETE FROM StartBiasIslands WHERE LeaderType IS NULL AND ((SELECT OffB FROM LShufWork_Cfg) = 1 OR ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1 AND CivilizationType IN (SELECT CivilizationType FROM LShufWork_Civ WHERE (SELECT RollBiases FROM LShufWork_Cfg) = 1 OR Donor <> CivilizationType)));
INSERT OR IGNORE INTO StartBiasIslands (CivilizationType, LeaderType, Score)
  SELECT r.CivilizationType, r.LeaderType, r.Score FROM LShufResultBiases r
  WHERE r.TableName = 'StartBiasIslands' AND r.Origin <> 'shipped'
    AND (r.LeaderType IS NULL OR r.LeaderType IN (SELECT LeaderType FROM Leaders))
    AND (r.CivilizationType IS NULL OR r.CivilizationType IN (SELECT CivilizationType FROM Civilizations));
DELETE FROM StartBiasResources WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'B'
    UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffB FROM LShufWork_Cfg) = 1 AND RB IS NULL);
DELETE FROM StartBiasResources WHERE LeaderType IS NULL AND ((SELECT OffB FROM LShufWork_Cfg) = 1 OR ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1 AND CivilizationType IN (SELECT CivilizationType FROM LShufWork_Civ WHERE (SELECT RollBiases FROM LShufWork_Cfg) = 1 OR Donor <> CivilizationType)));
INSERT OR IGNORE INTO StartBiasResources (CivilizationType, LeaderType, ResourceType, Score)
  SELECT r.CivilizationType, r.LeaderType, r.TargetType, r.Score FROM LShufResultBiases r
  WHERE r.TableName = 'StartBiasResources' AND r.Origin <> 'shipped'
    AND (r.LeaderType IS NULL OR r.LeaderType IN (SELECT LeaderType FROM Leaders))
    AND (r.CivilizationType IS NULL OR r.CivilizationType IN (SELECT CivilizationType FROM Civilizations)) AND r.TargetType IN (SELECT ResourceType FROM Resources);
CREATE TABLE IF NOT EXISTS LShufWork_LCP (Civilization TEXT, Leader TEXT, Priority INTEGER);
DELETE FROM LShufWork_LCP;
INSERT INTO LShufWork_LCP (Civilization, Leader, Priority) SELECT Civilization, Leader, Priority FROM LeaderCivPriorities
  WHERE Leader IN (SELECT PersonaFrom FROM LShufWork_L);
DELETE FROM LeaderCivPriorities WHERE Leader IN (SELECT LeaderType FROM LShufWork_L WHERE PersonaFrom IS NOT NULL AND PersonaFrom <> LeaderType);
INSERT OR IGNORE INTO LeaderCivPriorities (Civilization, Leader, Priority)
  SELECT c.Civilization, l.LeaderType, c.Priority FROM LShufWork_L l JOIN LShufWork_LCP c ON c.Leader = l.PersonaFrom
  WHERE l.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE PersonaFrom IS NOT NULL AND PersonaFrom <> LeaderType) AND c.Civilization IN (SELECT CivilizationType FROM Civilizations);

-- Civilization builds (CONTRACTS 14): ability swaps, then the moved uniques on a trait of the builder civ's own.
CREATE TABLE IF NOT EXISTS LShufWork_CivTraitSwap (Civ TEXT, OldTrait TEXT, NewTrait TEXT, PRIMARY KEY (Civ, OldTrait));
DELETE FROM LShufWork_CivTraitSwap;
INSERT OR IGNORE INTO LShufWork_CivTraitSwap (Civ, OldTrait, NewTrait)
  SELECT r.CivilizationType, i.Ability, s.Ability FROM LShufResultCivPieces r
  JOIN LShufWork_CivInfo i ON i.Civ = r.CivilizationType JOIN LShufWork_CivInfo s ON s.Civ = r.FromCivilization
  WHERE r.Kind = 'ability';
UPDATE CivilizationTraits SET TraitType = (SELECT w.NewTrait FROM LShufWork_CivTraitSwap w
    WHERE w.Civ = CivilizationTraits.CivilizationType AND w.OldTrait = CivilizationTraits.TraitType)
  WHERE EXISTS (SELECT 1 FROM LShufWork_CivTraitSwap w WHERE w.Civ = CivilizationTraits.CivilizationType
    AND w.OldTrait = CivilizationTraits.TraitType AND w.NewTrait IN (SELECT TraitType FROM Traits));
INSERT OR IGNORE INTO Types (Type, Kind) SELECT DISTINCT 'TRAIT_LSHUF_CIV_' || CivilizationType, 'KIND_TRAIT' FROM LShufResultCivPieces
  WHERE Kind IN ('unique', 'civics') AND CivilizationType IN (SELECT CivilizationType FROM Civilizations);
INSERT OR IGNORE INTO Traits (TraitType, InternalOnly) SELECT DISTINCT 'TRAIT_LSHUF_CIV_' || CivilizationType, 1 FROM LShufResultCivPieces
  WHERE Kind IN ('unique', 'civics') AND 'TRAIT_LSHUF_CIV_' || CivilizationType IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO CivilizationTraits (CivilizationType, TraitType) SELECT DISTINCT CivilizationType, 'TRAIT_LSHUF_CIV_' || CivilizationType
  FROM LShufResultCivPieces WHERE Kind IN ('unique', 'civics') AND CivilizationType IN (SELECT CivilizationType FROM Civilizations)
    AND 'TRAIT_LSHUF_CIV_' || CivilizationType IN (SELECT TraitType FROM Traits);
UPDATE Units SET TraitType = (SELECT 'TRAIT_LSHUF_CIV_' || r.CivilizationType FROM LShufResultCivPieces r WHERE r.Kind = 'unique'
    AND (r.PieceId = 'CIVUNQ_' || Units.UnitType OR Units.UnitType LIKE substr(r.PieceId, 8) || '\_%' ESCAPE '\'))
  WHERE EXISTS (SELECT 1 FROM LShufResultCivPieces r WHERE r.Kind = 'unique'
    AND (r.PieceId = 'CIVUNQ_' || Units.UnitType OR Units.UnitType LIKE substr(r.PieceId, 8) || '\_%' ESCAPE '\')
    AND 'TRAIT_LSHUF_CIV_' || r.CivilizationType IN (SELECT TraitType FROM Traits));
UPDATE Improvements SET TraitType = (SELECT 'TRAIT_LSHUF_CIV_' || r.CivilizationType FROM LShufResultCivPieces r WHERE r.Kind = 'unique' AND r.PieceId = 'CIVUNQ_' || ConstructibleType)
  WHERE 'CIVUNQ_' || ConstructibleType IN (SELECT PieceId FROM LShufResultCivPieces WHERE Kind = 'unique') AND (SELECT 'TRAIT_LSHUF_CIV_' || r.CivilizationType FROM LShufResultCivPieces r WHERE r.Kind = 'unique' AND r.PieceId = 'CIVUNQ_' || ConstructibleType) IN (SELECT TraitType FROM Traits);
-- The main-tree nodes that unlock a moved unique (its whole family) ask for the new civ's trait instead of the source's.
UPDATE ProgressionTreeNodeUnlocks SET RequiredTraitType = (SELECT 'TRAIT_LSHUF_CIV_' || r.CivilizationType FROM LShufResultCivPieces r
    JOIN LShufWork_CivInfo s ON s.Civ = r.FromCivilization
    WHERE r.Kind = 'unique' AND s.Base = ProgressionTreeNodeUnlocks.RequiredTraitType
      AND (r.PieceId = 'CIVUNQ_' || ProgressionTreeNodeUnlocks.TargetType
        OR ProgressionTreeNodeUnlocks.TargetType LIKE substr(r.PieceId, 8) || '\_%' ESCAPE '\'))
  WHERE EXISTS (SELECT 1 FROM LShufResultCivPieces r JOIN LShufWork_CivInfo s ON s.Civ = r.FromCivilization
    WHERE r.Kind = 'unique' AND s.Base = ProgressionTreeNodeUnlocks.RequiredTraitType
      AND (r.PieceId = 'CIVUNQ_' || ProgressionTreeNodeUnlocks.TargetType
        OR ProgressionTreeNodeUnlocks.TargetType LIKE substr(r.PieceId, 8) || '\_%' ESCAPE '\')
      AND 'TRAIT_LSHUF_CIV_' || r.CivilizationType IN (SELECT TraitType FROM Traits));
-- Civilization abilities Off for everyone (CONTRACTS 16): every civ's ability trait row goes, except a civ that took one.
DELETE FROM CivilizationTraits WHERE (SELECT CA FROM LShufWork_Cfg) = 'LSHUF_OFF'
  AND TraitType IN (SELECT Ability FROM LShufWork_CivInfo)
  AND CivilizationType NOT IN (SELECT CivilizationType FROM LShufResultCivPieces WHERE Kind = 'ability');
-- Civilization uniques Off for everyone: every unique goes onto a trait no civ holds, except the ones builders took.
INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_NONE', 'KIND_TRAIT' WHERE (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_OFF';
INSERT OR IGNORE INTO Traits (TraitType, InternalOnly) SELECT 'TRAIT_LSHUF_NONE', 1 WHERE 'TRAIT_LSHUF_NONE' IN (SELECT Type FROM Types);
UPDATE Units SET TraitType = 'TRAIT_LSHUF_NONE'
  WHERE (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_OFF' AND 'TRAIT_LSHUF_NONE' IN (SELECT TraitType FROM Traits)
    AND TraitType IN (SELECT Base FROM LShufWork_CivInfo) AND 'CIVUNQ_' || UnitType NOT IN (SELECT PieceId FROM LShufResultCivPieces WHERE Kind = 'unique') AND UnitType NOT IN (SELECT UnitType FROM LShufWork_CivicUnit);
UPDATE Improvements SET TraitType = 'TRAIT_LSHUF_NONE'
  WHERE (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_OFF' AND 'TRAIT_LSHUF_NONE' IN (SELECT TraitType FROM Traits)
    AND TraitType IN (SELECT Base FROM LShufWork_CivInfo) AND 'CIVUNQ_' || ConstructibleType NOT IN (SELECT PieceId FROM LShufResultCivPieces WHERE Kind = 'unique') AND ConstructibleType NOT IN (SELECT u.TargetType FROM ProgressionTreeNodeUnlocks u JOIN ProgressionTreeNodes n
    ON n.ProgressionTreeNodeType = u.ProgressionTreeNodeType WHERE n.ProgressionTree LIKE 'TREE\_CIVICS\_%' ESCAPE '\' AND n.ProgressionTree NOT LIKE '%\_MAIN' ESCAPE '\');
-- Unique civics (CONTRACTS 18): every civ that gives its civics (or loses them to Off) gets a trait of its own for
-- its units and main-tree improvements, then its base trait goes to the receiver.
INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_CIV_' || Civ, 'KIND_TRAIT' FROM LShufWork_CivInfo WHERE Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL));
INSERT OR IGNORE INTO Traits (TraitType, InternalOnly) SELECT 'TRAIT_LSHUF_CIV_' || Civ, 1 FROM LShufWork_CivInfo
  WHERE Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL)) AND 'TRAIT_LSHUF_CIV_' || Civ IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO CivilizationTraits (CivilizationType, TraitType) SELECT Civ, 'TRAIT_LSHUF_CIV_' || Civ FROM LShufWork_CivInfo
  WHERE Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL)) AND Civ IN (SELECT CivilizationType FROM Civilizations) AND 'TRAIT_LSHUF_CIV_' || Civ IN (SELECT TraitType FROM Traits);
UPDATE Units SET TraitType = (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = TraitType)
  WHERE TraitType IN (SELECT d.Base FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL))) AND (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = TraitType) IN (SELECT TraitType FROM Traits) AND UnitType NOT IN (SELECT UnitType FROM LShufWork_CivicUnit);
UPDATE Improvements SET TraitType = (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = TraitType)
  WHERE TraitType IN (SELECT d.Base FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL))) AND (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = TraitType) IN (SELECT TraitType FROM Traits) AND ConstructibleType NOT IN (SELECT u.TargetType FROM ProgressionTreeNodeUnlocks u JOIN ProgressionTreeNodes n
    ON n.ProgressionTreeNodeType = u.ProgressionTreeNodeType WHERE n.ProgressionTree LIKE 'TREE\_CIVICS\_%' ESCAPE '\' AND n.ProgressionTree NOT LIKE '%\_MAIN' ESCAPE '\');
UPDATE ProgressionTreeNodeUnlocks SET RequiredTraitType = (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = RequiredTraitType)
  WHERE RequiredTraitType IN (SELECT d.Base FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL))) AND (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = RequiredTraitType) IN (SELECT TraitType FROM Traits);
UPDATE ProgressionTreeNodeUnlocks SET NotTraitType = (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = NotTraitType)
  WHERE NotTraitType IN (SELECT d.Base FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL))) AND (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = NotTraitType) IN (SELECT TraitType FROM Traits);
UPDATE CivilizationTraits SET CivilizationType = (SELECT r.CivilizationType FROM LShufResultCivPieces r JOIN LShufWork_CivInfo d ON d.Civ = r.FromCivilization
    WHERE r.Kind = 'civics' AND d.Base = CivilizationTraits.TraitType AND d.Civ = CivilizationTraits.CivilizationType)
  WHERE (SELECT r.CivilizationType FROM LShufResultCivPieces r JOIN LShufWork_CivInfo d ON d.Civ = r.FromCivilization
    WHERE r.Kind = 'civics' AND d.Base = CivilizationTraits.TraitType AND d.Civ = CivilizationTraits.CivilizationType) IN (SELECT CivilizationType FROM Civilizations);
-- Civilization civics Off for everyone: the base trait of every civ whose civics didn't move goes to nobody.
DELETE FROM CivilizationTraits WHERE (SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND TraitType IN (SELECT d.Base FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL)))
  AND TraitType NOT IN (SELECT d.Base FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics'));
-- An ability's own modifiers that ask for the civ's base trait (MOD_CIV_WONDER_PRODUCTION_<CIV>) ask for the ability
-- trait instead, so they follow the ability wherever it goes (CONTRACTS 14).
UPDATE RequirementArguments SET Value = Value || '_ABILITY'
  WHERE Name = 'TraitType' AND Value IN (SELECT Base FROM LShufWork_CivInfo) AND Value || '_ABILITY' IN (SELECT TraitType FROM Traits)
    AND RequirementId IN (SELECT rsr.RequirementId FROM RequirementSetRequirements rsr JOIN Modifiers m
      ON m.SubjectRequirementSetId = rsr.RequirementSetId OR m.OwnerRequirementSetId = rsr.RequirementSetId
      JOIN TraitModifiers tm ON tm.ModifierId = m.ModifierId WHERE tm.TraitType = RequirementArguments.Value || '_ABILITY');
-- Civilization abilities = Split (CONTRACTS 19): the copy path for every civ holding pieces.
CREATE TABLE IF NOT EXISTS LShufWork_CivCopy (Receiver TEXT, ModifierId TEXT, PRIMARY KEY (Receiver, ModifierId));
DELETE FROM LShufWork_CivCopy;
INSERT OR IGNORE INTO LShufWork_CivCopy (Receiver, ModifierId)
  SELECT r.CivilizationType, mm.ModifierId FROM LShufResultCivPieces r JOIN LShufCivMappingModifiers mm ON mm.PieceId = r.PieceId
  WHERE r.Kind = 'bullet' AND mm.Role IN ('effect', 'hidden')
    AND mm.ModifierId IN (SELECT tm.ModifierId FROM TraitModifiers tm WHERE tm.TraitType = (SELECT i.Ability FROM LShufWork_CivInfo i WHERE i.Civ = r.FromCivilization));
INSERT OR IGNORE INTO LShufWork_CivCopy (Receiver, ModifierId)
  SELECT r.CivilizationType, tm.ModifierId FROM LShufResultCivPieces r JOIN LShufWork_CivInfo i ON i.Civ = r.CivilizationType
  JOIN TraitModifiers tm ON tm.TraitType = i.Ability
  WHERE r.Kind = 'remainder' AND tm.ModifierId NOT IN (SELECT mm.ModifierId FROM LShufCivMappingModifiers mm JOIN LShufCivMapping m ON m.PieceId = mm.PieceId
      WHERE m.CivilizationType = r.CivilizationType AND m.Kind = 'bullet' AND m.Movable = 1 AND m.Age = i.Age);
DELETE FROM LShufWork_CivCopy WHERE ModifierId NOT IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_CIVA_' || Civ, 'KIND_TRAIT' FROM LShufWork_CivInfo WHERE Civ IN (SELECT DISTINCT CivilizationType FROM LShufResultCivPieces WHERE Kind IN ('bullet', 'remainder'));
INSERT OR IGNORE INTO Traits (TraitType, Name, Description, InternalOnly)
  SELECT 'TRAIT_LSHUF_CIVA_' || i.Civ, i.AbilityName, 'LOC_LSHUF_TRAIT_CIV_DEALT_DESCRIPTION', 1 FROM LShufWork_CivInfo i
  WHERE i.Civ IN (SELECT DISTINCT CivilizationType FROM LShufResultCivPieces WHERE Kind IN ('bullet', 'remainder')) AND 'TRAIT_LSHUF_CIVA_' || i.Civ IN (SELECT Type FROM Types);
UPDATE CivilizationTraits SET TraitType = 'TRAIT_LSHUF_CIVA_' || CivilizationType
  WHERE CivilizationType IN (SELECT DISTINCT CivilizationType FROM LShufResultCivPieces WHERE Kind IN ('bullet', 'remainder')) AND TraitType = (SELECT i.Ability FROM LShufWork_CivInfo i WHERE i.Civ = CivilizationTraits.CivilizationType)
    AND 'TRAIT_LSHUF_CIVA_' || CivilizationType IN (SELECT TraitType FROM Traits);
INSERT OR IGNORE INTO Modifiers (ModifierId, ModifierType, NewOnly, OwnerRequirementSetId, OwnerStackLimit, Permanent, RunOnce,
    SubjectRequirementSetId, SubjectStackLimit)
  SELECT 'LSHUF_' || c.Receiver || '__' || m.ModifierId, m.ModifierType, m.NewOnly, m.OwnerRequirementSetId, m.OwnerStackLimit, m.Permanent, m.RunOnce,
    m.SubjectRequirementSetId, m.SubjectStackLimit FROM LShufWork_CivCopy c JOIN Modifiers m ON m.ModifierId = c.ModifierId;
INSERT OR IGNORE INTO ModifierArguments (ModifierId, Name, Extra, SecondExtra, Type, Value)
  SELECT 'LSHUF_' || c.Receiver || '__' || a.ModifierId, a.Name, a.Extra, a.SecondExtra, a.Type,
    CASE WHEN a.Name = 'Tooltip' AND (SELECT i.AbilityName FROM LShufWork_CivInfo i WHERE i.Civ = c.Receiver) IS NOT NULL THEN (SELECT i.AbilityName FROM LShufWork_CivInfo i WHERE i.Civ = c.Receiver) ELSE a.Value END
  FROM LShufWork_CivCopy c JOIN ModifierArguments a ON a.ModifierId = c.ModifierId
  WHERE 'LSHUF_' || c.Receiver || '__' || a.ModifierId IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO ModifierStrings (Context, ModifierId, Text)
  SELECT s.Context, 'LSHUF_' || c.Receiver || '__' || s.ModifierId, s.Text FROM LShufWork_CivCopy c JOIN ModifierStrings s ON s.ModifierId = c.ModifierId
  WHERE 'LSHUF_' || c.Receiver || '__' || s.ModifierId IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO TraitModifiers (ModifierId, TraitType)
  SELECT 'LSHUF_' || c.Receiver || '__' || c.ModifierId, 'TRAIT_LSHUF_CIVA_' || c.Receiver FROM LShufWork_CivCopy c
  WHERE 'LSHUF_' || c.Receiver || '__' || c.ModifierId IN (SELECT ModifierId FROM Modifiers) AND 'TRAIT_LSHUF_CIVA_' || c.Receiver IN (SELECT TraitType FROM Traits);
UPDATE RequirementArguments SET Value = 'TRAIT_LSHUF_CIVA_' || (SELECT i.Civ FROM LShufWork_CivInfo i WHERE i.Ability = RequirementArguments.Value)
  WHERE Name = 'TraitType' AND Value IN (SELECT i.Ability FROM LShufWork_CivInfo i WHERE i.Civ IN (SELECT DISTINCT CivilizationType FROM LShufResultCivPieces WHERE Kind IN ('bullet', 'remainder')))
    AND RequirementId IN (SELECT rsr.RequirementId FROM RequirementSetRequirements rsr JOIN Modifiers m
      ON m.SubjectRequirementSetId = rsr.RequirementSetId OR m.OwnerRequirementSetId = rsr.RequirementSetId
      JOIN TraitModifiers tm ON tm.ModifierId = m.ModifierId WHERE tm.TraitType = RequirementArguments.Value);
